SELECT o.id::pg_catalog.text AS record_id, o.type_id::pg_catalog.text AS record_type_id, o.root_id::pg_catalog.text AS root_id, o.root_type::pg_catalog.text AS root_type_id, o.ver::pg_catalog.text AS record_version, o.rev::pg_catalog.text AS catalog_revision, o.created_at::pg_catalog.text AS created_at_text, o.updated_at::pg_catalog.text AS updated_at_text, o.props::pg_catalog.text AS properties_text, o.retained::pg_catalog.text AS retained_text, pg_catalog.current_setting('DateStyle') AS date_style, pg_catalog.current_setting('TimeZone') AS time_zone FROM truss.object o WHERE o.id = $1::bigint AND o.type_id = $2::int LIMIT 2; SELECT e.id::pg_catalog.text AS record_id, e.rel_type_id::pg_catalog.text AS record_type_id, e.source_id::pg_catalog.text AS source_id, e.source_type::pg_catalog.text AS source_type_id, e.target_id::pg_catalog.text AS target_id, e.target_type::pg_catalog.text AS target_type_id, e.order_key AS order_key, e.ver::pg_catalog.text AS record_version, e.rev::pg_catalog.text AS catalog_revision, e.created_at::pg_catalog.text AS created_at_text, e.updated_at::pg_catalog.text AS updated_at_text, e.props::pg_catalog.text AS properties_text, pg_catalog.current_setting('DateStyle') AS date_style, pg_catalog.current_setting('TimeZone') AS time_zone FROM truss.edge e WHERE e.id = $1::bigint AND e.rel_type_id = $2::int LIMIT 2